      const dot = row.createSpan({ cls: "mt-dashboard-pie__dot" });
      dot.style.setProperty("--mt-segment-color", segment.color);
      row.createSpan({ cls: "mt-dashboard-pie__legend-label", text: segment.label, attr: { title: segment.label } });
      const percent = Math.round(segment.value / total * 100);
